-- =============================================================================
-- 0001_baseline.sql
-- Portal Integrado da Rede de Prestadores — Unimed Criciúma (RN ANS 630/2024)
-- Baseline Postgres (substitui o schema SQLite embutido no server.ts).
--
-- Convenções:
--   * Chaves: bigint GENERATED BY DEFAULT AS IDENTITY (permite seed com id explícito)
--   * Tempo:  timestamptz para instantes, date para datas de calendário
--   * Dinheiro/pesos: numeric (nunca float) — pesos de roteiro podem ser fracionários
--   * Booleanos: boolean (não 0/1)
--   * JSON: jsonb
--   * FKs sempre indexadas; ON DELETE explícito
-- Idempotente: seguro reexecutar (CREATE TABLE IF NOT EXISTS).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- NÚCLEO: prestadores (origem SGU), locais de atendimento, equipe, usuários
-- -----------------------------------------------------------------------------

-- Prestador / cooperado — 1 linha por código único do SGU.
CREATE TABLE IF NOT EXISTS providers (
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sgu_code           text UNIQUE,                 -- código único do prestador (chave de integração SGU)
  name               text NOT NULL,               -- razão social / nome
  trade_name         text,                        -- nome fantasia
  person_type        text CHECK (person_type IN ('PF','PJ')),  -- pessoa física/jurídica
  cnpj               text,                         -- nulo para PF
  cpf                text,                         -- nulo para PJ
  council_registry   text,                         -- registro no conselho (CRM/CRO/etc.)
  specialties        jsonb NOT NULL DEFAULT '[]'::jsonb,  -- especialidades (normalizar depois se preciso)
  provider_group     text,
  qualification_level text,
  status             text,                         -- 'ativo', 'inativo', ...
  source             text NOT NULL DEFAULT 'manual', -- 'sgu' | 'manual'
  sgu_synced_at      timestamptz,                  -- último upsert vindo do SGU
  created_at         timestamptz NOT NULL DEFAULT now()
);
-- CNPJ/CPF únicos quando presentes (PF não tem CNPJ; PJ não tem CPF).
CREATE UNIQUE INDEX IF NOT EXISTS providers_cnpj_uniq ON providers (cnpj) WHERE cnpj IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS providers_cpf_uniq  ON providers (cpf)  WHERE cpf  IS NOT NULL;

-- Locais de atendimento — N por prestador (um código pode ter vários endereços).
CREATE TABLE IF NOT EXISTS provider_locations (
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id        bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  sgu_location_code  text,                         -- código do local no SGU, se houver
  label              text,                         -- identificação do local
  cep                text,
  logradouro         text,
  numero             text,
  complemento        text,
  bairro             text,
  cidade             text,
  uf                 char(2),
  phone              text,
  is_primary         boolean NOT NULL DEFAULT false,
  in_medical_guide   boolean NOT NULL DEFAULT false, -- consta no guia médico (§5.4.1.1)
  active             boolean NOT NULL DEFAULT true,
  created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS provider_locations_provider_idx ON provider_locations (provider_id);
CREATE UNIQUE INDEX IF NOT EXISTS provider_locations_sgu_uniq
  ON provider_locations (provider_id, sgu_location_code) WHERE sgu_location_code IS NOT NULL;

-- Equipe do prestador (contatos/profissionais) — informativos, SEM login (§5.2.3).
CREATE TABLE IF NOT EXISTS provider_contacts (
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id        bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  name               text NOT NULL,
  position           text,                         -- cargo / função
  email              text,
  phone              text,
  cpf                text,
  council_registry   text,
  is_active          boolean NOT NULL DEFAULT true,
  created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS provider_contacts_provider_idx ON provider_contacts (provider_id);

-- Usuários com acesso ao portal (perfis distintos).
-- Perfis do escopo: Auditor/Analista, Administrador, Prestador/Cooperado.
CREATE TABLE IF NOT EXISTS users (
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name               text NOT NULL,
  email              text UNIQUE NOT NULL,
  password           text NOT NULL,
  role               text NOT NULL
                       CHECK (role IN ('prestador','cooperado','admin','auditoria')),
  provider_id        bigint REFERENCES providers(id) ON DELETE SET NULL,
  is_active          boolean NOT NULL DEFAULT true,
  last_login_at      timestamptz,                  -- último acesso (data) — §5.2.2 Tela 4
  last_login_ip      text,                         -- último acesso (IP)
  created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS users_provider_idx ON users (provider_id);

-- Trilha de acessos (auditoria de login).
CREATE TABLE IF NOT EXISTS access_logs (
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id            bigint REFERENCES users(id) ON DELETE SET NULL,
  email              text,                         -- preservado mesmo se o usuário sumir
  ip                 text,
  user_agent         text,
  success            boolean NOT NULL DEFAULT true,
  created_at         timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS access_logs_user_idx ON access_logs (user_id);
CREATE INDEX IF NOT EXISTS access_logs_created_idx ON access_logs (created_at);

-- Log de sincronização SGU → Postgres (WS2).
CREATE TABLE IF NOT EXISTS sgu_sync_runs (
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source             text NOT NULL,                -- 'db' | 'csv' | 'dump'
  status             text NOT NULL DEFAULT 'running' CHECK (status IN ('running','success','error')),
  providers_upserted integer NOT NULL DEFAULT 0,
  locations_upserted integer NOT NULL DEFAULT 0,
  message            text,
  started_at         timestamptz NOT NULL DEFAULT now(),
  finished_at        timestamptz
);

-- -----------------------------------------------------------------------------
-- DOCUMENTOS / CHAMADOS / COMUNICAÇÃO
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS documents (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  type            text NOT NULL,
  issue_date      date,
  expiry_date     date,
  status          text NOT NULL,                   -- valido|pendente|reprovado|vencido|historico
  file_url        text,
  upload_date     timestamptz,
  uploaded_by     bigint REFERENCES users(id) ON DELETE SET NULL,
  rejection_reason text
);
CREATE INDEX IF NOT EXISTS documents_provider_idx ON documents (provider_id);

CREATE TABLE IF NOT EXISTS tickets (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  title           text NOT NULL,
  description     text NOT NULL,
  category        text NOT NULL,
  priority        text NOT NULL,
  status          text NOT NULL,                   -- aberto|em_analise|respondido|encerrado
  response        text,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS tickets_provider_idx ON tickets (provider_id);

CREATE TABLE IF NOT EXISTS ticket_messages (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ticket_id       bigint NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
  user_id         bigint REFERENCES users(id) ON DELETE SET NULL,
  user_name       text NOT NULL,
  role            text NOT NULL,
  message         text NOT NULL,
  is_status_change boolean NOT NULL DEFAULT false,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ticket_messages_ticket_idx ON ticket_messages (ticket_id);

CREATE TABLE IF NOT EXISTS announcements (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title           text NOT NULL,
  description     text NOT NULL,
  category        text NOT NULL,
  image_url       text,
  date            timestamptz NOT NULL DEFAULT now()
);

-- -----------------------------------------------------------------------------
-- TREINAMENTOS / FINANCEIRO / AUDITORIAS / CONTRATOS
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS trainings (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title           text NOT NULL,
  description     text,
  video_url       text,
  pdf_url         text,
  validity_days   integer,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS provider_trainings (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  training_id     bigint NOT NULL REFERENCES trainings(id) ON DELETE CASCADE,
  status          text NOT NULL,                   -- pendente|em_andamento|concluido
  completed_at    timestamptz
);
CREATE INDEX IF NOT EXISTS provider_trainings_provider_idx ON provider_trainings (provider_id);
CREATE INDEX IF NOT EXISTS provider_trainings_training_idx ON provider_trainings (training_id);

CREATE TABLE IF NOT EXISTS financials (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  competence      text NOT NULL,
  gross_value     numeric(14,2) NOT NULL,
  glosa_value     numeric(14,2) NOT NULL,
  net_value       numeric(14,2) NOT NULL,
  status          text
);
CREATE INDEX IF NOT EXISTS financials_provider_idx ON financials (provider_id);

CREATE TABLE IF NOT EXISTS audits (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  scheduled_date  date NOT NULL,
  status          text NOT NULL,                   -- programada|realizada
  evaluation      text
);
CREATE INDEX IF NOT EXISTS audits_provider_idx ON audits (provider_id);

CREATE TABLE IF NOT EXISTS contracts (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  title           text NOT NULL,
  file_url        text NOT NULL,
  status          text NOT NULL,                   -- pendente|ativo|vencido
  signed_at       date,
  expires_at      date,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS contracts_provider_idx ON contracts (provider_id);

-- -----------------------------------------------------------------------------
-- QUALIFICAÇÃO (modelo legado por ciclos — mantido para compatibilidade)
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS qualifications (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  cycle           text NOT NULL,
  score           integer,
  status          text NOT NULL,                   -- pendente|em_andamento|concluida
  seal            text,                            -- Ouro|Prata|Bronze|null
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS qualifications_provider_idx ON qualifications (provider_id);

CREATE TABLE IF NOT EXISTS qualification_cycles (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title           text NOT NULL,
  description     text,
  active          boolean NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS qualification_items (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  cycle_id        bigint NOT NULL REFERENCES qualification_cycles(id) ON DELETE CASCADE,
  title           text NOT NULL,
  description     text,
  is_required     boolean NOT NULL DEFAULT true,
  type            text DEFAULT 'file',
  na_allowed      boolean NOT NULL DEFAULT true
);
CREATE INDEX IF NOT EXISTS qualification_items_cycle_idx ON qualification_items (cycle_id);

CREATE TABLE IF NOT EXISTS qualification_submissions (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id       bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  cycle_id          bigint NOT NULL REFERENCES qualification_cycles(id) ON DELETE CASCADE,
  status            text NOT NULL,                 -- rascunho|enviado|em_analise|aprovado|reprovado|parcial
  submitted_at      timestamptz,
  evaluated_at      timestamptz,
  evaluated_by      bigint REFERENCES users(id) ON DELETE SET NULL,
  final_observations text,
  created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS qualification_submissions_provider_idx ON qualification_submissions (provider_id);
CREATE INDEX IF NOT EXISTS qualification_submissions_cycle_idx ON qualification_submissions (cycle_id);

CREATE TABLE IF NOT EXISTS qualification_submission_items (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  submission_id     bigint NOT NULL REFERENCES qualification_submissions(id) ON DELETE CASCADE,
  item_id           bigint NOT NULL REFERENCES qualification_items(id) ON DELETE CASCADE,
  is_compliant      boolean,
  evidence_url      text,
  auditor_status    text,                          -- aprovado|reprovado|pendente
  auditor_observation text,
  text_answer       text,
  justification     text,
  is_na             boolean NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS qualification_submission_items_submission_idx ON qualification_submission_items (submission_id);

CREATE TABLE IF NOT EXISTS action_plans (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  title           text NOT NULL,
  description     text NOT NULL,
  deadline        date NOT NULL,
  status          text NOT NULL,                   -- pendente|em_andamento|concluido
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS action_plans_provider_idx ON action_plans (provider_id);

CREATE TABLE IF NOT EXISTS price_tables (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint REFERENCES providers(id) ON DELETE CASCADE, -- null = geral
  title           text NOT NULL,
  code            text NOT NULL,
  version         text NOT NULL,
  status          text NOT NULL,                   -- vigente|futura|historico
  effective_date  date NOT NULL,
  file_url        text NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS price_tables_provider_idx ON price_tables (provider_id);

CREATE TABLE IF NOT EXISTS credentialing_requests (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name            text NOT NULL,
  email           text NOT NULL,
  phone           text NOT NULL,
  specialty       text NOT NULL,
  file_url        text,
  status          text NOT NULL DEFAULT 'pendente',
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS qualification_scripts (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title           text NOT NULL,
  items           jsonb NOT NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS survey_responses (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id     bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  atendimento     text NOT NULL,
  comunicacao     text NOT NULL,
  sugestoes       text,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS survey_responses_provider_idx ON survey_responses (provider_id);

CREATE TABLE IF NOT EXISTS settings (
  key             text PRIMARY KEY,
  value           text NOT NULL
);

-- -----------------------------------------------------------------------------
-- MOTOR DE ROTEIROS DE QUALIFICAÇÃO (RN 630) — destino da carga dos 15 .xlsx
-- Pesos/escores em numeric: roteiros podem ter pesos fracionários.
-- -----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS eval_scripts (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title           text NOT NULL,
  description     text,
  version         text,
  source_file     text,                            -- arquivo .xlsx de origem (rastreabilidade)
  created_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS eval_sections (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  script_id         bigint NOT NULL REFERENCES eval_scripts(id) ON DELETE CASCADE,
  parent_section_id bigint REFERENCES eval_sections(id) ON DELETE CASCADE,
  name              text NOT NULL,
  order_index       integer NOT NULL
);
CREATE INDEX IF NOT EXISTS eval_sections_script_idx ON eval_sections (script_id);
CREATE INDEX IF NOT EXISTS eval_sections_parent_idx ON eval_sections (parent_section_id);

CREATE TABLE IF NOT EXISTS eval_questions (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  section_id      bigint NOT NULL REFERENCES eval_sections(id) ON DELETE CASCADE,
  code            text,
  text            text NOT NULL,
  legislation     text,
  type            text NOT NULL,                   -- sim_nao|multipla_escolha|texto|numerico|data|upload|checklist
  options         jsonb,
  weight          numeric(8,2) NOT NULL DEFAULT 1, -- peso máximo do critério
  max_score       numeric(8,2) NOT NULL DEFAULT 0,
  dimension       text,                            -- dimensão do critério (roteiro)
  evidence_required boolean NOT NULL DEFAULT false,
  is_eliminatory  boolean NOT NULL DEFAULT false,
  order_index     integer NOT NULL
);
CREATE INDEX IF NOT EXISTS eval_questions_section_idx ON eval_questions (section_id);

CREATE TABLE IF NOT EXISTS eval_instances (
  id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  script_id           bigint NOT NULL REFERENCES eval_scripts(id) ON DELETE CASCADE,
  provider_id         bigint NOT NULL REFERENCES providers(id) ON DELETE CASCADE,
  auditor_id          bigint REFERENCES users(id) ON DELETE SET NULL,
  status              text NOT NULL,               -- em_andamento|pendente|em_analise|aguardando_evidencia|reprovado|aprovado|finalizado
  score               numeric(10,2) NOT NULL DEFAULT 0,
  max_possible_score  numeric(10,2) NOT NULL DEFAULT 0,
  percentual          numeric(6,2) NOT NULL DEFAULT 0,
  seal                text,                        -- Bronze|Prata|Ouro|null
  started_at          timestamptz NOT NULL DEFAULT now(),
  completed_at        timestamptz
);
CREATE INDEX IF NOT EXISTS eval_instances_script_idx ON eval_instances (script_id);
CREATE INDEX IF NOT EXISTS eval_instances_provider_idx ON eval_instances (provider_id);

CREATE TABLE IF NOT EXISTS eval_answers (
  id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  instance_id         bigint NOT NULL REFERENCES eval_instances(id) ON DELETE CASCADE,
  question_id         bigint NOT NULL REFERENCES eval_questions(id) ON DELETE CASCADE,
  answer_value        text,                        -- opção/valor selecionado ou 'NA'
  score_obtained      numeric(8,2),
  evidence_url        text,
  provider_observation text,
  auditor_observation text,
  is_non_compliant    boolean NOT NULL DEFAULT false,
  evidence_status     text                         -- pendente|aprovado|reprovado
);
CREATE INDEX IF NOT EXISTS eval_answers_instance_idx ON eval_answers (instance_id);
CREATE INDEX IF NOT EXISTS eval_answers_question_idx ON eval_answers (question_id);
